                 Tracked(other.perms.borrow().tracked_borrow((other.len() - count) as nat).3));

             let next = *ptr_ref(p, Tracked(&other.perms.borrow().tracked_borrow((other.len() - count) as nat).0));
             if next.ptr.addr() != 0 {
